-- Dev-only catalog rows for Northdale on the LAN (entry served by pnpm --filter @rally/game-northdale dev on :5186,
-- strictPort). Generated from `publish-game northdale --dry-run` (publish-plan.json): the games row, the manifest, the
-- `nights` (best) / `kills` (best) / `escapes` (total) boards and the five achievements; art is left out (the dry run's
-- CDN URLs are placeholders; a real publish uploads it). Replace 10.0.0.201 with the PC LAN IP. Re-runnable. The game
-- server must be v5 (the `northdale` room). The real publish adds 0.1.0 next to this -dev version and repoints
-- current_version_id.
insert into public.games (id,title,description,genres,screenshots,icon_url,cover_url,engine,orientation,min_players,max_players,modes,age_rating,min_app_version,status)
values ('northdale','Northdale','Up to four survivors are trapped in the town of Northdale. By day, roam the open streets: crack open chests, search wrecks and trash for weapons, ammo, medkits and scrap, and fortify the safehouse with barricades. By night the dead come in hordes, and every night they come stronger, with crawlers, bursting chubbies and rock-throwing brutes, and a Blood Moon every fifth night. Find the stray dog, bring home wheels and fuel to fix the armored truck, and from Night 4 make a run for the Northdale gantry, or see how many nights you can last. The boards keep your most nights survived, your most kills in a run, and your total escapes.',array['action','survival','shooter']::text[],'{}'::text[],null,null,'playcanvas','landscape',1,4,array['quick','browser','private']::public.game_mode[],'12+','0.0.0','published')
on conflict (id) do update set title=excluded.title, description=excluded.description, genres=excluded.genres, min_players=excluded.min_players, max_players=excluded.max_players, modes=excluded.modes, age_rating=excluded.age_rating, status='published';

